import { Router } from "express";
import { getAdminDashboard } from "../controllers/admin.controller.js";
import { authenticateToken } from "../middleware/jwt.js";
import { requireAdmin } from "../middleware/requireAdmin.js";
import { getAdminPayments } from "../controllers/admin-payment.controller.js";
import { listPendingPlayerPayments, reviewPlayerPayment, } from "../controllers/adminPlayerPayment.controller.js";
const router = Router();
router.get("/dashboard", authenticateToken, requireAdmin, getAdminDashboard);
router.get("/payments", authenticateToken, requireAdmin, getAdminPayments);
router.get("/player-payments", authenticateToken, requireAdmin, listPendingPlayerPayments);
router.patch("/player-payments/:paymentId/review", authenticateToken, requireAdmin, reviewPlayerPayment);
export default router;
